/**
 * Fictional demo data for FindMaxxing.
 *
 * Every user, place and event here is invented. Names, tips and descriptions
 * are illustrative only and must not be read as real recommendations.
 * Coordinates sit in real Columbus, Ohio neighborhoods so the map looks alive.
 *
 * This file is the single source of truth for BOTH:
 *   - the demo-mode store (src/lib/data/demo)
 *   - supabase/seed.sql (generated by `npm run seed:sql`)
 */
import { createHash } from "node:crypto";

/** Deterministic UUID-shaped id from a label, so seeds are stable. */
export function stableId(label: string): string {
  const h = createHash("sha256").update(`findmaxxing:${label}`).digest("hex");
  // Format as a v4-looking UUID (variant bits set) so uuid validators accept it.
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-4${h.slice(13, 16)}-a${h.slice(17, 20)}-${h.slice(20, 32)}`;
}

export const DEMO_PASSWORD = "findmaxxing";
export const SEED_CITY = "Columbus";

export interface SeedUser {
  id: string;
  email: string;
  username: string;
  displayName: string;
  bio: string;
  homeCity: string;
  interests: string[];
}

export interface SeedPlace {
  id: string;
  name: string;
  description: string;
  localTip: string;
  categorySlug: string;
  lat: number;
  lng: number;
  address: string | null;
  neighborhood: string;
  city: string;
  creator: string; // username
  tags: string[];
  /** Defaults to "public". "locals" exercises the trust tier. */
  visibility?: "public" | "locals";
}

export interface SeedEvent {
  id: string;
  title: string;
  description: string;
  place: string | null; // seed place name
  locationName: string;
  address: string | null;
  lat: number;
  lng: number;
  /** Days from "now" (may be negative for past events). */
  startsInDays: number;
  startHour: number; // 24h local
  startMinute: number;
  durationMinutes: number | null;
  creator: string; // username
  categorySlug: string;
  capacity: number | null;
  tags: string[];
  attendees: string[]; // usernames
}

export interface SeedRating {
  place: string;
  user: string;
  score: number;
  note: string | null;
}

const u = (username: string) => stableId(`user:${username}`);
const p = (name: string) => stableId(`place:${name}`);
const e = (title: string) => stableId(`event:${title}`);

