export function seedUserByName(username: string): SeedUser {
  const found = SEED_USERS.find((x) => x.username === username);
  if (!found) throw new Error(`Unknown seed user ${username}`);
  return found;
}
export function seedPlaceByName(name: string): SeedPlace {
  const found = SEED_PLACES.find((x) => x.name === name);
  if (!found) throw new Error(`Unknown seed place ${name}`);
  return found;
}

/** Resolve a seed event's start/end as absolute Dates relative to `now`. */
export function seedEventTimes(ev: SeedEvent, now = new Date()): { startsAt: Date; endsAt: Date | null } {
  const start = new Date(now.getFullYear(), now.getMonth(), now.getDate() + ev.startsInDays, ev.startHour, ev.startMinute, 0, 0);
  const end = ev.durationMinutes ? new Date(start.getTime() + ev.durationMinutes * 60_000) : null;
  return { startsAt: start, endsAt: end };
}
